import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";var i=JSON.parse(`{"title":"고유가피해지원금","description":"고유가피해지원금에 대해 알아봅니다.","frontmatter":{"title":"고유가피해지원금","date":"2026-05-25T20:26+09:00","description":"고유가피해지원금에 대해 알아봅니다.","tags":["고유가피해지원금","연구수당"]},"headers":[],"relativePath":"sleep/oil-price-support.md","filePath":"sleep/oil-price-support.md","lastUpdated":1783689122000}`),a={name:`sleep/oil-price-support.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="고유가피해지원금" tabindex="-1">고유가피해지원금 <a class="header-anchor" href="#고유가피해지원금" aria-label="Permalink to “고유가피해지원금”">​</a></h1><p>고유가피해지원금은 <mark>2026년 3월 30일 기준 국내 거주 중인 소득 하위 70%에 해당되는 가구</mark>들이 받을 수 있어요. 그런데 저는 그 기준에 포함되지 않는지 대상자 조회에서 제외되었더라고요. 한편 같이 세대를 구성하고 있는 여자친구는 지원 대상에 포함되었어요.</p><h2 id="동거인은-가구원-산정에서-제외돼요" tabindex="-1">동거인은 가구원 산정에서 제외돼요 <a class="header-anchor" href="#동거인은-가구원-산정에서-제외돼요" aria-label="Permalink to “동거인은 가구원 산정에서 제외돼요”">​</a></h2><p>주민등록등본상 여자친구와 같은 세대를 구성하고 있어도 결혼하지 않은 동거인은 가구 산정에서 제외되어 1인 가구로 분류돼요. <mark>1인 가구 기준으로 월 소득 약 385만 원 이하인 경우</mark>라면 지원 대상에 포함될 수 있다고 나와 있어요.</p><p>그런데 저는 <a href="https://www.nhis.or.kr/nhis/minwon/retrieveStimmyInit2.do" target="_blank" rel="noreferrer">국민건강보험의 고유가 피해지원금 2차 대상자 조회</a>를 이용하면 대상자가 아니라고 나와요. 그래서 <a href="https://www.nhis.or.kr/nhis/minwon/minwonServiceBoard.do?mode=view&amp;articleNo=10945799" target="_blank" rel="noreferrer">보험료 조회</a>를 해보니 3월 건강보험료가 이전보다 거의 2배 가까이 부과되었더라고요. <mark>제 건강보험료 납부액이 이전보다 거의 2배 가까이 늘어난 이유가 뭘까요?</mark></p><h2 id="연구수당이-소득에-포함돼요" tabindex="-1">연구수당이 소득에 포함돼요 <a class="header-anchor" href="#연구수당이-소득에-포함돼요" aria-label="Permalink to “연구수당이 소득에 포함돼요”">​</a></h2><p>바로 정부 연구 과제 참여로 인한 <strong>연구수당</strong> 지급 때문이었어요. 평소에는 소득 하위 70% 이하에 해당되는 월급을 받고 있지만, 연구 과제에 참여하고 종료되면서 받게 된 연구수당이 2월에 지급되었고 <mark>연구수당도 소득이므로 건강보험료 산정에 포함</mark>되었던 것이죠. 결국 3월 건강보험료가 이전보다 거의 2배 가까이 부과되면서 고유가피해지원금 기준으로는 소득 상위 30%의 국민이 되어버렸어요. <strong>연봉을 나누어서 수령하거나 상여금을 받게 된 직장인분들도</strong> 이와 같은 불이익을 받을 수 있겠더라고요.</p><blockquote><p>국민신문고 <a href="https://www.epeople.go.kr/nsf/Intro.html" target="_blank" rel="noreferrer">고유가 피해지원금 지급 이의신청</a>으로 서류를 제출해 이의신청을 해볼 수 있지만, 저의 경우에는 연구수당 지급명세서를 발급받아서 제출해야 하기 때문에 증빙 절차가 복잡해서 따로 신청하지는 않으려고 해요.</p></blockquote><h2 id="이사로-인한-주소지-변경-시-사용-지역-변경하기" tabindex="-1">이사로 인한 주소지 변경 시 사용 지역 변경하기 <a class="header-anchor" href="#이사로-인한-주소지-변경-시-사용-지역-변경하기" aria-label="Permalink to “이사로 인한 주소지 변경 시 사용 지역 변경하기”">​</a></h2><p>고유가피해지원금이 3월 30일 기준의 주민등록으로 신청되기 때문에, 여자친구는 현재 주소지가 다르기 때문에 카드사 앱을 통해 현재 주민등록상 주소지로 사용지역을 변경해서 사용해야 한다네요.</p><p>고유가피해지원금 신청 덕분에 <strong>세대 구성이 그대로 가구가 아니다</strong>라는 걸 알게 되었어요.</p>`,11)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};